from pathlib import Path
import json,hashlib,shutil,datetime,urllib.request,urllib.parse
r=Path(__file__).resolve().parent;root=r.parent.parent;p=r/'private/native';out=Path.home()/'Videos/Studio - Cut Through - 2026-11-08';out.mkdir(exist_ok=True);tech=out/'Technical';tech.mkdir(exist_ok=True);sources=out/'Sources';sources.mkdir(exist_ok=True)
def read(f):return json.loads(Path(f).read_text())
def sha(f):return hashlib.sha256(Path(f).read_bytes()).hexdigest()
def copy(a,b):
 a=Path(a);b=Path(b)
 if b.exists() and sha(a)!=sha(b):raise RuntimeError('Preserve previous delivered bytes: '+str(b))
 shutil.copy2(a,b)
